def cmp_semver(a, b):
    def parse_version(s):
        # Split into major, minor, patch
        parts = s.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Extract pre-release and build metadata
        pre_release = None
        build = None

        if '+' in s:
            s = s.split('+')[0]
        if '-' in s:
            s, build = s.split('-', 1)
            pre_release = s.split('.')
        else:
            pre_release = []

        return (major, minor, patch, pre_release, build)

    def compare_pre_release(pre_a, pre_b):
        # If one is None (empty list), it means no pre-release
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1  # No pre-release > pre-release
        if pre_b is None:
            return -1  # Pre-release < no pre-release

        # Compare identifiers
        for i in range(max(len(pre_a), len(pre_b))):
            if i >= len(pre_a):
                return -1  # Shorter list loses if all preceding are equal
            if i >= len(pre_b):
                return 1

            id_a = pre_a[i]
            id_b = pre_b[i]

            # Check if numeric
            is_num_a = id_a.isdigit()
            is_num_b = id_b.isdigit()

            if is_num_a and is_num_b:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a != num_b:
                    return -1 if num_a < num_b else 1
            elif is_num_a:
                return -1  # Numeric < Alphanumeric
            elif is_num_b:
                return 1  # Alphanumeric > Numeric
            else:
                # Both alphanumeric, compare lexicographically
                if id_a != id_b:
                    return -1 if id_a < id_b else 1

        return 0

    ver_a = parse_version(a)
    ver_b = parse_version(b)

    # Compare major, minor, patch
    for i in range(3):
        if ver_a[i] != ver_b[i]:
            return -1 if ver_a[i] < ver_b[i] else 1

    # Compare pre-release
    return compare_pre_release(ver_a[3], ver_b[3])
