def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header (str): The value of the Range header (e.g., "bytes=0-499").
        size (int): The total size of the resource in bytes.

    Returns:
        list: A list of (start, end) inclusive byte offsets, or None if unsatisfiable.
    """
    if not header.startswith("bytes="):
        return None

    ranges_str = header[6:]  # Remove "bytes="
    if not ranges_str:
        return None

    ranges = []
    parts = ranges_str.split(",")

    for part in parts:
        part = part.strip()
        if not part:
            continue

        if "-" not in part:
            continue

        suffix_length = part.startswith("-")

        if suffix_length:
            # Format: -500
            if not part[1:].isdigit():
                continue
            length = int(part[1:])
            if length <= 0:
                continue
            start = size - length
            if start < 0:
                start = 0
            end = size - 1
            ranges.append((start, end))
        else:
            # Format: 0-499 or 500-
            indices = part.split("-")
            if len(indices) != 2:
                continue

            start_str, end_str = indices

            if start_str == "":
                # Format: -500 (already handled above, but for safety)
                # Actually, if it's not starting with '-', this branch shouldn't happen for suffix
                # But if input is just "-", it's invalid
                continue

            if end_str == "":
                # Format: 500-
                try:
                    start = int(start_str)
                except ValueError:
                    continue

                if start < 0 or start >= size:
                    continue

                end = size - 1
                ranges.append((start, end))
            else:
                # Format: 0-499
                try:
                    start = int(start_str)
                    end = int(end_str)
                except ValueError:
                    continue

                if start < 0 or end < 0:
                    continue

                if start > end:
                    continue

                # Clamp end to size - 1
                end = min(end, size - 1)

                # If start is past the last byte, this range is unsatisfiable
                if start >= size:
                    continue

                ranges.append((start, end))

    if not ranges:
        return None

    return ranges
