        while len(self.history) > target_index:
            root_b, root_a, old_size = self.history.pop()
            self.parent[root_b] = root_b
            self.size[root_a] = old_size

    def components(self):
        return sum(1 for i in range(len(self.parent)) if self.parent[i] == i)

