    def __init__(self):
        self.root = {}
        self.word_count = 0  # Tracks how many times each word is stored

    def add(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['$'] = node.get('$', 0) + 1

    def remove(self, word: str) -> bool:
        node = self.root
        for char in word:
            if char not in node:
                return False
            node = node[char]
        if '$' not in node:
            return False
        node['$'] -= 1
        return node['$'] > 0

