import heapq

def topo_lex(graph):
    # Collect all unique nodes from both keys and values
    all_nodes = set(graph.keys())
    for successors in graph.values():
        all_nodes.update(successors)

    # Calculate in-degree for each node
    in_degree = {node: 0 for node in all_nodes}

    for node, successors in graph.items():
        for successor in successors:
            in_degree[successor] += 1

    # Initialize heap with nodes that have in-degree 0
    # Use a min-heap to get lexicographically smallest node
    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []

    while heap:
        # Pop the smallest node
        current = heapq.heappop(heap)
        result.append(current)

        # Decrease in-degree of successors
        if current in graph:
            for successor in graph[current]:
                in_degree[successor] -= 1
                if in_degree[successor] == 0:
                    heapq.heappush(heap, successor)

    # Check if all nodes are included (no cycle)
    if len(result) != len(all_nodes):
        return None

    return result

