module.exports = function sqlTag(strings, ...expressions) {
  let text = '';
  let values = [];
  let placeholderCounter = 0;

  const getPlaceholder = (val) => {
    if (val === undefined || val === null) return '';
    if (typeof val === 'string') return val;
    if (typeof val === 'number') return val;
    if (typeof val === 'boolean') return val ? '1' : '0';
    if (typeof val === 'object') {
      if (val.sqlTagResult) {
        // Inline nested sqlTag result
        return val.sqlTagResult.text;
      }
      if (Array.isArray(val)) {
        // Array becomes parenthesised comma-separated list
        const inner = val.map(getPlaceholder).join(', ');
        return `(${inner})`;
      }
      // Object literal is not supported per spec, treat as string or throw
      return JSON.stringify(val);
    }
    return String(val);
  };

  const addPlaceholder = (val) => {
    const ph = `$${++placeholderCounter}`;
    values.push(getPlaceholder(val));
    return ph;
  };

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    if (i < expressions.length) {
      text += addPlaceholder(expressions[i]);
    }
  }

  return { text, values };
};

