module.exports = function chunkAsync(source, size) {
  if (typeof size !== 'number' || size < 1) {
    throw new Error('size must be a positive integer');
  }

  return async function* () {
    const buffer = [];
    let iterator;

    try {
      iterator = source[Symbol.asyncIterator]?.() || source[Symbol.iterator]?.();
      if (!iterator) {
        throw new TypeError('source is not iterable');
      }

      while (true) {
        // Pull up to `size` items
        for (let i = 0; i < size; i++) {
          const value = await iterator.next();
          if (value.done) {
            // End of source
            if (buffer.length > 0) {
              yield buffer;
            }
            break;
          }
          buffer.push(value.value);
        }

        if (buffer.length === 0) {
          // Source ended cleanly with no remaining items
          break;
        }

        // Yield the current chunk
        yield buffer;
        buffer.length = 0;
      }
    } finally {
      // Ensure the iterator's return method is called if the consumer stops early
      if (iterator && typeof iterator.return === 'function') {
        await iterator.return();
      }
    }
  };
};

