export class Bus<E extends Record<string, unknown>> {
  private handlers = new Map<keyof E, Map<keyof E, ((payload: E[keyof E]) => void)[]>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.handlers.has(k)) {
      this.handlers.set(k, new Map());
    }
    const eventHandlers = this.handlers.get(k)!;
    if (!eventHandlers.has(k)) {
      eventHandlers.set(k, []);
    }
    eventHandlers.get(k)!.push(fn);
    return () => {
      const eventHandlers = this.handlers.get(k);
      if (eventHandlers) {
        const handlers = eventHandlers.get(k);
        if (handlers) {
          const index = handlers.indexOf(fn);
          if (index > -1) {
            handlers.splice(index, 1);
            if (handlers.length === 0) {
              eventHandlers.delete(k);
            }
          }
        }
        if (eventHandlers.size === 0) {
          this.handlers.delete(k);
        }
      }
    };
  }

  emit<K extends keyof E>(k: K, payload?: E[K]): void {
    const eventHandlers = this.handlers.get(k);
    if (!eventHandlers) return;

    const handlers = eventHandlers.get(k);
    if (!handlers) return;

    if (E[k] === void) {
      handlers.forEach(fn => fn(payload as any));
    } else {
      if (payload === undefined) {
        throw new Error(`Event "${String(k)}" requires a payload`);
      }
      handlers.forEach(fn => fn(payload));
    }
  }
}

