module.exports = function toposortTasks(tasks) {
  const result = new Map();
  const errorMap = new Map();
  const pending = new Set();
  const completed = new Set();
  const inProgress = new Set();
  const queue = [];

  // Build adjacency list and in-degree count for topological sort
  const graph = {};
  const inDegree = {};

  for (const [name, config] of Object.entries(tasks)) {
    graph[name] = config.deps || [];
    inDegree[name] = 0;
  }

  for (const [name, deps] of Object.entries(graph)) {
    for (const dep of deps) {
      if (!tasks.hasOwnProperty(dep)) {
        throw new Error(`Unknown dependency: ${dep}`);
      }
      inDegree[name]++;
    }
  }

  // Initialize queue with nodes having no dependencies
  for (const [name, degree] of Object.entries(inDegree)) {
    if (degree === 0) {
      queue.push(name);
    }
  }

  // Helper to check for cycles during execution
  function detectCycle(name) {
    if (inProgress.has(name)) {
      throw new Error(`Dependency cycle detected involving task: ${name}`);
    }
    if (completed.has(name)) {
      return false;
    }
    return true;
  }

  // Process tasks in topological order
  while (queue.length > 0) {
    const current = queue.shift();
    inProgress.add(current);

    if (!detectCycle(current)) {
      // This shouldn't happen if logic is correct, but safety check
      inProgress.delete(current);
      continue;
    }

    try {
      const task = tasks[current];
      const depsValues = {};

      // Gather dependency values
      for (const dep of task.deps) {
        if (!result.has(dep)) {
          throw new Error(`Missing dependency value for: ${dep}`);
