  if (!qs) return {};

  const result = {};
  const decoder = new TextDecoder('utf-8');
  const encoder = new TextEncoder();

  const pairs = qs.split('&');
  for (const pair of pairs) {
    const eqIndex = pair.indexOf('=');
    let key, value;
    if (eqIndex === -1) {
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Decode percent encoding and handle '+' as space
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    const decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

    // Handle bracket notation
    if (decodedKey.includes('[') && decodedKey.includes(']')) {
      const parts = decodedKey.split(/(\[|\])/).filter(Boolean);
      let current = result;
      for (let i = 0; i < parts.length; i++) {
        const part = parts[i];
        if (part === '[') {
          // Next part is the key inside brackets
          const nextPart = parts[i + 1];
          if (current[nextPart] === undefined) {
            current[nextPart] = [];
          } else if (!Array.isArray(current[nextPart])) {
            // If it's not an array yet, convert to array
            current[nextPart] = [current[nextPart]];
          }
          current = current[nextPart];
          i++; // Skip next part as we consumed it
        } else if (part === ']') {
          // End of bracket sequence, move up
          if (i > 0) {
            const prevPart = parts[i - 1];
            if (Array.isArray(current)) {
              current.push({});
              current = current[current.length - 1];
            } else {
              current = {};
            }
          }
        } else {
          // Regular key
          if (current[part] === undefined) {
            current[part] = decodedValue;
          } else if (Array.isArray(current[part])) {
