export type Result<T, E> =
  | { readonly _tag: 'ok'; readonly value: T }
  | { readonly _tag: 'err'; readonly error: E };

export function ok<T, E>(value: T): Result<T, E> {
  return { _tag: 'ok', value };
}

export function err<T, E>(error: E): Result<T, E> {
  return { _tag: 'err', error };
}

export function isOk<T, E>(result: Result<T, E>): result is Result<T, E> {
  return result._tag === 'ok';
}

export function isErr<T, E>(result: Result<T, E>): result is Result<T, E> {
  return result._tag === 'err';
}

export function map<T, E, U>(
  result: Result<T, E>,
  f: (value: T) => U
): Result<U, E> {
  return isOk(result) ? ok(f(result.value)) : err(result.error);
}

export function unwrapOr<T, E>(
  result: Result<T, E>,
  defaultValue: T
): T {
  return isOk(result) ? result.value : defaultValue;
}

export default Result;

