export type RouteParams<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer Name}` ? Name : never;
}[keyof T];

export type RouteHandler<T extends Record<string, string>> = T extends never
  ? () => string
  : <P extends RouteParams<T>>(params: { [K in keyof P]: string }) => string;

export type DefinedRoutes<T extends Record<string, string>> = {
  [K in keyof T]: T[K] extends `:${infer Name}`
    ? Name extends string
      ? RouteHandler<{ [Key in Name]: string }>
      : never
    : RouteHandler<never>;
};

export function defineRoutes<T extends Record<string, string>>(
  routes: T
): DefinedRoutes<T> {
  const result: DefinedRoutes<T> = {} as DefinedRoutes<T>;

  for (const [name, path] of Object.entries(routes)) {
    const paramKeys = path.match(/:(\w+)/g)?.map((m) => m.slice(1)) || [];
    const paramMap = new Map(paramKeys.map((k) => [k, k]));

    const handler = (params: { [K in keyof typeof paramMap]: string }) => {
      let interpolated = path;
      for (const [key, value] of Object.entries(params)) {
        interpolated = interpolated.replace(`:${key}`, value);
      }
      return interpolated;
    } as any;

    result[name] = handler;
  }

  return result;
}

